set-variable.value:
@{
			string path = context.Request.MatchedParameters.GetValueOrDefault("path", "");
			string marker = "deployments/";
			int markerIndex = path.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
			if (markerIndex < 0) { return true; }
			int start = markerIndex + marker.Length;
			int end = path.IndexOf('/', start);
			string pathDeployment = end < 0 ? path.Substring(start) : path.Substring(start, end - start);
			string detectedModel = context.Variables.GetValueOrDefault<string>("model", "");
			return !string.IsNullOrWhiteSpace(pathDeployment) &&
				string.Equals(pathDeployment, detectedModel, StringComparison.OrdinalIgnoreCase);
		}

@{
			JObject loaded = context.Variables.GetValueOrDefault<JObject>("throttleState", null);
			JObject map = (loaded != null && loaded["backends"] != null && loaded["backends"].Type == JTokenType.Object) ? (JObject)loaded["backends"] : new JObject();
			return new JObject(
				new JProperty("dirty", false),
				new JProperty("backends", map)
			);
		}

@{
			JArray backends = (JArray)context.Variables["listBackends"];
			JObject state = (JObject)((JObject)context.Variables["throttleState"])["backends"];
			DateTime now = DateTime.UtcNow;
			foreach (JObject b in backends) {
				DateTime wakeAt = state.Value<DateTime?>(b.Value<string>("affinity")) ?? DateTime.MinValue;
				bool isThrottling = wakeAt > now;
				b["isThrottling"] = isThrottling;
				b["retryAfter"] = isThrottling ? wakeAt : DateTime.MinValue;
			}
			return backends;
		}

@{
			const int defaultPriority = 3;
			string priorityHeaderName = (string)context.Variables["priorityHeaderName"];
			return context.Request.Headers.TryGetValue(priorityHeaderName, out var priorityValues) &&
				int.TryParse(priorityValues.FirstOrDefault(), out int parsedPriority)
				? parsedPriority
				: defaultPriority;
		}

@{
			string affinityHeaderName = (string)context.Variables["AffinityHeaderName"];
			string affinityHeader = context.Request.Headers.GetValueOrDefault(affinityHeaderName, "");

			// Find the backend with the matching affinity
			if (!string.IsNullOrEmpty(affinityHeader)) {
				JArray backends = (JArray)context.Variables["listBackends"];
				for (int i = 0; i < backends.Count; i++) {
					JObject backend = (JObject)backends[i];
					if (string.Equals(backend["affinity"]?.ToString(), affinityHeader, StringComparison.OrdinalIgnoreCase)) {
						return i;  // Return the index of the matching backend
					}
				}
			}

			// Return -1 if no affinity header or no match found
			return -1;
		}

@{
			JArray list =  new JArray();
			JArray backends = (JArray)context.Variables["listBackends"];
			int requestPriority = (int)context.Variables["RequestPriority"];
			for (int i = 0; i < backends.Count; i++) {
				JObject backend = (JObject)backends[i];
				if (backend["acceptablePriorities"]?.Values<int>().Contains(requestPriority) == true) {
					list.Add(i);
				}
			}
			return list;
		}

@{
			return ((JObject)context.Variables["priorityCfg"])
				.GetValue(context.Variables.GetValueOrDefault<int>("RequestPriority", 3).ToString())?
				.Value<int>("retryCount") ?? 1;
		}

@{
			return ((JObject)context.Variables["priorityCfg"])
				.GetValue(context.Variables.GetValueOrDefault<int>("RequestPriority", 3).ToString())?
				.Value<bool>("requeue") ?? true;
		}

@{
			string policyCycleCounterHeaderName = (string)context.Variables["PolicyCycleCounterHeaderName"];
			return context.Request.Headers.TryGetValue(policyCycleCounterHeaderName, out var priorityValues) &&
				int.TryParse(priorityValues.FirstOrDefault(), out int parsedCounter)   ? parsedCounter : 0;   // return 0 if not set
		}

@{
			// Initialize or reuse
			JArray arr = context.Variables.GetValueOrDefault<JArray>("lastPolicyError", new JArray());
			arr.Clear();
			arr.Add(new JObject {
				{ "code", "init" },
				{ "message", "noError" }
			});
			return arr;
		}

@{
			// Request Start
			JArray arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
			arr.Clear();
			arr.Add(new JObject {
				{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3")},
				{ "message", "Begin" }
			});
			return arr;
		}

@{
			var headers = context.Request.Headers;
			if (!string.Equals(headers.GetValueOrDefault("S7PDEBUG", ""), "true", StringComparison.OrdinalIgnoreCase)) {
				return "";
			}

			string priorityHeaderName = (string)context.Variables["priorityHeaderName"];
			JObject dbgObj = new JObject {
				{ "Proxy-Queue-Duration", headers.GetValueOrDefault("x-Request-Queue-Duration", "N/A") },
				{ "Proxy-Process-Duration", headers.GetValueOrDefault("x-Request-Process-Duration", "N/A") },
				{ "S7PID", headers.GetValueOrDefault("x-S7P-ID", "N/A") },
				{ priorityHeaderName, headers.GetValueOrDefault(priorityHeaderName, "N/A") },
				{ "Priority", context.Variables.GetValueOrDefault<int>("RequestPriority", 3) }
			};

			return string.Join(" | ", dbgObj.Properties().Select(p => p.Name + ": " + p.Value));
		}

@{
				JObject loaded = context.Variables.GetValueOrDefault<JObject>("throttleState", null);
				JObject map = (loaded != null && loaded["backends"] != null && loaded["backends"].Type == JTokenType.Object) ? (JObject)loaded["backends"] : new JObject();
				return new JObject(
					new JProperty("dirty", false),
					new JProperty("backends", map)
				);
			}

@{
				JArray backends = (JArray)context.Variables["listBackends"];
				JObject state = (JObject)((JObject)context.Variables["throttleState"])["backends"];
				DateTime now = DateTime.UtcNow;
				foreach (JObject b in backends) {
					DateTime wakeAt = state.Value<DateTime?>(b.Value<string>("affinity")) ?? DateTime.MinValue;
					bool isThrottling = wakeAt > now;
					b["isThrottling"] = isThrottling;
					b["retryAfter"] = isThrottling ? wakeAt : DateTime.MinValue;
				}
				return backends;
			}

@{
				// Error Scenario
				JArray backends = (JArray)context.Variables["listBackends"];
				JArray priorityBackendIndxs = (JArray)context.Variables["PriBackendIndxs"];
				JObject wrapper = (JObject)context.Variables["throttleState"];
				JObject state = (JObject)wrapper["backends"];
				var backendIndex = context.Variables.GetValueOrDefault<int>("backendIndex", -1);
				var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
				var elapsedStr = context.Elapsed.TotalSeconds.ToString("F3");
				var callAttempted = context.Variables.GetValueOrDefault<bool>("callAttempted", false);
				DateTime now = DateTime.UtcNow;
				if ( backendIndex < 0 || backendIndex >= backends.Count) {

					if ( callAttempted ) {
						arr.Add(new JObject {{ "Elapsed", elapsedStr },{ "message", $"Invalid backend index: {backendIndex}" }});
					} else {
						var throttled = new List<string>();

						foreach (int i in priorityBackendIndxs) {
							JObject b = (JObject)backends[i];
							if (!b.Value<bool>("isThrottling")) {
								continue;
							}

							DateTime retryAfter = b.Value<DateTime>("retryAfter");
							var remainingSeconds = retryAfter > now
								? (int)Math.Ceiling((retryAfter - now).TotalSeconds)
								: 0;
							var retryAfterText = string.Format("{0:00}:{1:00}", remainingSeconds / 60, remainingSeconds % 60);
							throttled.Add(b.Value<string>("label") + " - " + retryAfterText);
						}

						string msg = "THROTTLED: (" + (throttled.Count > 0 ? string.Join(", ", throttled) : "none") + ")";

						arr.Add(new JObject {{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },{ "message", msg }});
					}
					return 4; // unknown
				}

				JObject backend = (JObject)backends[backendIndex];
				var lastStatusCode = context.Response?.StatusCode ?? 0;
				var callCompleted = context.Variables.GetValueOrDefault<bool>("callCompleted", true);
				var wasLimited = context.Variables.GetValueOrDefault<bool>("wasLimited", false);
				var startTime = context.Variables.GetValueOrDefault<DateTime>("CallAttemptStartTime", now);
				var deltaSeconds = (now - startTime).TotalSeconds;
				var requestTimeout = backend.Value<int>("timeout");
				bool likelyTimeout = deltaSeconds >= (requestTimeout * 0.9);
				string label = backend.Value<string>("label");
				string id = backend.Value<string>("affinity");

				if ( callCompleted ) {
					return lastStatusCode == 200 ? 0 : 1;
				}

				if ( likelyTimeout || wasLimited || lastStatusCode >= 500 ) {
					// Not completed with a throttle-worthy signal: record in the shared map (by id)
					DateTime wakeAt = now.AddSeconds(10);
					DateTime existingWake = state.Value<DateTime?>(id) ?? DateTime.MinValue;
					if (wakeAt > existingWake) { state[id] = wakeAt; wrapper["dirty"] = true; }
					backend["isThrottling"] = true;
					backend["retryAfter"] = state.Value<DateTime?>(id) ?? wakeAt;
				}

				int scenario;
				string message;
				if ( likelyTimeout) {
					scenario = 2; // timeout
					message = $"Throttling {label} by 10s, likely timeout Elapsed: {deltaSeconds:F1}s Timeout: {requestTimeout}s";
				} else if ( wasLimited ) {
					scenario = 3; // concurrency limit
					message = $"Throttling {label} by 10s, concurrency limit";
				} else if ( lastStatusCode >= 500 ) {
					scenario = 1; // error
					message = $"Throttling {label} by 10s, status {lastStatusCode}";
				} else {
					scenario = 4; // unknown
					message = $"Error status {lastStatusCode} after {deltaSeconds:F1}s";
				}

				arr.Add(new JObject {{ "Elapsed", elapsedStr },{ "message", message }});
				return scenario;
			}

@{
				try {
					JArray backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
					JArray priorityBackendIndxs = context.Variables.GetValueOrDefault<JArray>("PriBackendIndxs", new JArray());
					if (backends.Count == 0 || priorityBackendIndxs.Count == 0) { return -1; }

					bool contextWindowExceeded = context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false);
					int backendCallCount = context.Variables.GetValueOrDefault<int>("backendCallCounter", 0);
					if (backendCallCount == 0 && !contextWindowExceeded) {
						int affinityBackendIdx = context.Variables.GetValueOrDefault<int>("RequestAffinityBackendIdx", -1);
						if (affinityBackendIdx >= 0 && affinityBackendIdx < backends.Count) {
							JObject affinityBackend = (JObject)backends[affinityBackendIdx];
							if (!affinityBackend.Value<bool>("isThrottling")) {
								return affinityBackendIdx;
							}
						}
					}

					var availableBackends = new List<int>();
					int lowestPriority = int.MaxValue;
					foreach (int i in priorityBackendIndxs) {
						JObject backend = (JObject)backends[i];
						if (backend.Value<bool>("isThrottling") || (contextWindowExceeded && backend.Value<string>("label") == "PTU")) {
							continue;
						}

						int priority = backend.Value<int>("priorityGroup");
						if (priority > lowestPriority) {
							continue;
						}

						if (priority < lowestPriority) {
							lowestPriority = priority;
							availableBackends.Clear();
						}

						availableBackends.Add(i);
					}

					return availableBackends.Count == 0
						? -1
						: availableBackends[new Random(context.RequestId.GetHashCode()).Next(availableBackends.Count)];
				} catch (Exception ex) {
					var errArr = context.Variables.GetValueOrDefault<JArray>("lastPolicyError", null);
					if (errArr != null) {
						errArr.Clear();
						var msg = ex.Message ?? "Exception has no Message";
						if (msg.Length > 300) {
							msg = msg.Substring(0, 300) + "...";
						}
						errArr.Add(new JObject {
							{ "code", "backendIndex-update" },
							{ "message", msg },
							{ "utc", DateTime.UtcNow.ToString("o") }
						});
					}

					return -1;
				}


			}

@{
				try {
				// Check if the backend should limit concurrency
				JArray backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
				int backendIndex = (int)context.Variables["backendIndex"];
				if (backendIndex < 0 || backendIndex >= backends.Count) { return "off"; }
				JObject backend = (JObject)backends[backendIndex];
				return backend.Value<string>("limitConcurrency");
				} catch (Exception ex) {
					var errArr = context.Variables.GetValueOrDefault<JArray>("lastPolicyError", null);
					if (errArr != null) {
						errArr.Clear();
						var msg = ex.Message ?? "Exception has no Message";
						if (msg.Length > 300) { msg = msg.Substring(0,300) + "..."; }
						errArr.Add(new JObject {
							{ "code", "shouldLimit-update" },
							{ "message", msg },
							{ "utc", DateTime.UtcNow.ToString("o") }
						});
					}
					return "off";
				}
			}

@{
				var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
				var backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
				var priorityBackendIndxs = context.Variables.GetValueOrDefault<JArray>("PriBackendIndxs", new JArray());
				bool contextWindowExceeded = context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false);
				int unthrottledCount = 0;
				foreach (int i in priorityBackendIndxs) {
					JObject backend = (JObject)backends[i];
					if (!backend.Value<bool>("isThrottling") && (!contextWindowExceeded || backend.Value<string>("label") != "PTU")) {
						unthrottledCount++;
					}
				}

				int remainingRetries = context.Variables.GetValueOrDefault<int>("RetryCount");
				int policyCycle = context.Variables.GetValueOrDefault<int>("PolicyCycleCounter");
				var retryState = remainingRetries == 0 ? "exhausted" : remainingRetries.ToString();
				arr.Add(new JObject {
					{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3")},
					{ "message", $"RETRIES LEFT: {retryState} CYCLE: {policyCycle} Unthrottled Backends: {unthrottledCount}" }
				});
				return arr;
			}

@{
						string path = context.Request.MatchedParameters.GetValueOrDefault("path", "");
						string requested = context.Variables.GetValueOrDefault<string>("model", "");
						string selected = context.Variables.GetValueOrDefault<string>("selectedDeployment", "");
						if (!string.IsNullOrEmpty(requested) && !string.IsNullOrEmpty(selected)) {
							path = path.Replace("deployments/" + requested + "/", "deployments/" + selected + "/");
						}
						return "/" + path.TrimStart('/');
					}

when.set-body:
@{
								JObject body = context.Request.Body.As<JObject>(preserveContent: true);
								if (body["model"] != null) {
									body["model"] = context.Variables.GetValueOrDefault<string>("selectedDeployment", body["model"].ToString());
								}
								return body.ToString(Newtonsoft.Json.Formatting.None);
							}

set-variable.value:
@{
						// Backend Selected
						var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
						int index = context.Variables.GetValueOrDefault<int>("backendIndex", 0);
						JObject backend = (JObject)((JArray)context.Variables["listBackends"])[index];
						arr.Add(new JObject {
							{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
							{ "message", "Using " + backend.Value<string>("label") + " URL: " + backend.Value<string>("url") +
								" LIMIT: " + context.Variables.GetValueOrDefault<string>("shouldLimit", "off") }
						});
						return arr;
					}

@{
						if (context.Response == null || context.Response.StatusCode != 400) { return false; }
						try {
							var body = context.Response.Body.As<JObject>(preserveContent: true);
							return body["error"]?["code"]?.ToString() == "context_length_exceeded";
						} catch { return false; }
					}

@{
						var statusCode = context.Response?.StatusCode ?? 500;
						var retryableBadRequest = context.Variables.GetValueOrDefault<bool>("isRetryableBadRequest", false);

						bool isTempError = statusCode == 429 || statusCode == 408 || (statusCode == 400 && retryableBadRequest) || statusCode >= 500;
						return isTempError;
					}

@{
						var isTempError = context.Variables.GetValueOrDefault<bool>("isTempError", false);
						var statusCode = context.Response?.StatusCode ?? 500;
						bool isPermError =  !isTempError && (statusCode >= 400 && statusCode < 500);
						return isPermError;
					}

@{
						// Response Classified
						var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
						var statusCode = context.Response?.StatusCode.ToString() ?? "N/A";
						var isPermError = context.Variables.GetValueOrDefault<bool>("isPermError", false);
						var isTempError = context.Variables.GetValueOrDefault<bool>("isTempError", false);
						if (isTempError) {
							return arr;
						}

						var statusSummary = isTempError ? "Temp Error" : (isPermError ? "Perm Error" : "Success");
						arr.Add(new JObject {
							{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
							{ "message", "StatusCode: " + statusCode + " - " + statusSummary }
						});
						return arr;
					}

@{
						// No Backend
						var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
						var priorityBackendIndxs = context.Variables.GetValueOrDefault<JArray>("PriBackendIndxs", new JArray());
						int retryCount = context.Variables.GetValueOrDefault<int>("RetryCount", 0);
						string message;

						if (priorityBackendIndxs.Count == 0) {
							message = "NO BACKENDS: none configured for priority " + context.Variables.GetValueOrDefault<int>("RequestPriority", 3);
						} else if (retryCount <= 0) {
							message = "NO BACKENDS: retries exhausted";
						} else {
							var backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
							bool contextWindowExceeded = context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false);
							var now = DateTime.UtcNow;
							var throttled = new List<string>();
							foreach (int i in priorityBackendIndxs) {
								JObject b = (JObject)backends[i];
								if (contextWindowExceeded && b.Value<string>("label") == "PTU") { continue; }
								if (!b.Value<bool>("isThrottling")) { continue; }
								var retryAfter = b.Value<DateTime>("retryAfter");
								var secs = retryAfter > now ? (int)Math.Ceiling((retryAfter - now).TotalSeconds) : 0;
								throttled.Add(b.Value<string>("label") + " - " + string.Format("{0:00}:{1:00}", secs / 60, secs % 60));
							}
							message = "NO BACKENDS: all throttled (" + (throttled.Count > 0 ? string.Join(", ", throttled) : "none") + ")";
						}

						arr.Add(new JObject {
							{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
							{ "message", message }
						});
						return arr;
					}

@{
				if (context.Response == null) { return context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false); }

				if (context.Response.StatusCode == 400 && context.Variables.GetValueOrDefault<bool>("isRetryableBadRequest", false)) {
					return true;
				}

				// Keep existing value if not a context window error
				return context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false);
			}

@{
						JObject loaded = context.Variables.GetValueOrDefault<JObject>("throttleState", null);
						JObject map = (loaded != null && loaded["backends"] != null && loaded["backends"].Type == JTokenType.Object) ? (JObject)loaded["backends"] : new JObject();
						JObject wrapper = new JObject(
							new JProperty("dirty", false),
							new JProperty("backends", map)
						);
						JArray backends = (JArray)context.Variables["listBackends"];
						int idx = (int)context.Variables["backendIndex"];
						if (idx < 0 || idx >= backends.Count) { return wrapper; }
						JObject backend = (JObject)backends[idx];
						string id = backend.Value<string>("affinity");

						// Retry-after from the response header, else the backend default
						int retryAfterSeconds = backend["defaultRetryAfter"].Value<int>();
						foreach (string headerName in new[] { "retry-after" }) {
							if (context.Response.Headers.Keys.Any(k => string.Equals(k, headerName, StringComparison.OrdinalIgnoreCase))) {
								string headerValue = context.Response.Headers[headerName].FirstOrDefault();
								if (int.TryParse(headerValue, out int parsedValue) && parsedValue > 0) { retryAfterSeconds = parsedValue + 2; break; }
							}
						}

						// Multi-process safe: keep the max wake time for this backend id
						DateTime newWake = DateTime.UtcNow.AddSeconds(retryAfterSeconds);
						DateTime existing = (map[id] != null && map[id].Type != JTokenType.Null) ? map[id].Value<DateTime>() : DateTime.MinValue;
						if (newWake > existing) { map[id] = newWake; wrapper["dirty"] = true; }

						DateTime effective = map[id].Value<DateTime>();
						backend["isThrottling"] = true;
						backend["retryAfter"] = effective;

						var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
						var remainingSeconds = effective > DateTime.UtcNow ? (int)Math.Ceiling((effective - DateTime.UtcNow).TotalSeconds) : 0;
						var retryAfterText = string.Format("{0:00}:{1:00}", remainingSeconds / 60, remainingSeconds % 60);
						var statusCode = context.Response?.StatusCode.ToString() ?? "N/A";
						arr.Add(new JObject {
							{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
							{ "message", "StatusCode: " + statusCode + " - Temp Error; THROTTLED: " + backend.Value<string>("label") + " Retry-After: " + retryAfterText }
						});

						return wrapper;
					}

@{
				var backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
				var priorityBackendIndxs = (JArray)context.Variables["PriBackendIndxs"];
				bool contextWindowExceeded = context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false);
				int count=0;
				foreach (int i in priorityBackendIndxs) {
					JObject backend = (JObject)backends[i];
					// Skip PTU backends if context window exceeded
					if (contextWindowExceeded && backend.Value<string>("label") == "PTU") {
						continue;
					}
					if (!backend.Value<bool>("isThrottling")) {
						count++;
					}
				}
				return count;
			}

@{
				var isPermError = context.Variables.GetValueOrDefault<bool>("isPermError", false);
				var retryCount = context.Variables.GetValueOrDefault<int>("RetryCount", -1);
				var unthrottled = context.Variables.GetValueOrDefault<int>("unThrottledBackends", 0);
				var RequeueAllowed = context.Variables.GetValueOrDefault<bool>("RequeueAllowed", true);
				var proxyWillRequeue = RequeueAllowed && (unthrottled == 0);

				// retryCount has already been decremented for the attempt just made.
				return (!isPermError && retryCount > 0) && !proxyWillRequeue;
			}

@{
				var isPermError = context.Variables.GetValueOrDefault<bool>("isPermError", false);
				var RetryRemaining = context.Variables.GetValueOrDefault<bool>("RetryRemaining", true);
				var RequeueAllowed = context.Variables.GetValueOrDefault<bool>("RequeueAllowed", true);
				var unthrottled = context.Variables.GetValueOrDefault<int>("unThrottledBackends", 0);

				return !isPermError && unthrottled == 0 && (RequeueAllowed || !RetryRemaining);
			}

@{
				// Retry Decision
				var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
				if (!context.Variables.GetValueOrDefault<bool>("Return429", false)) {
					return arr;
				}

				var backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
				var priorityBackendIndxs = (JArray)context.Variables["PriBackendIndxs"];
				var now = DateTime.UtcNow;
				var parts = new List<string>(priorityBackendIndxs.Count);
				foreach (int i in priorityBackendIndxs) {
					if (i < 0 || i >= backends.Count) { continue; }
					JObject backend = (JObject)backends[i];
					string label = backend.Value<string>("label");
					if (!backend.Value<bool>("isThrottling")) {
						parts.Add(label + " ready");
						continue;
					}

					DateTime retryAfter = backend.Value<DateTime>("retryAfter");
					int secs = retryAfter > now ? (int)Math.Ceiling((retryAfter - now).TotalSeconds) : 0;
					parts.Add(label + " " + string.Format("{0:00}:{1:00}", secs / 60, secs % 60));
				}

				arr.Add(new JObject {
					{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
					{ "message", "REQUEUE: " + string.Join(", ", parts) }
				});
				return arr;
			}

@{

						JArray backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
						JArray priorityBackendIndxs = (JArray)context.Variables["PriBackendIndxs"];
						DateTime minRetryTime  = DateTime.MaxValue;

						foreach (int i in priorityBackendIndxs) {
							if (backends[i].Value<bool>("isThrottling") && backends[i].Value<DateTime>("retryAfter") < minRetryTime) {
								minRetryTime = backends[i].Value<DateTime>("retryAfter");
							}
						}

						if (minRetryTime > DateTime.UtcNow)  {
							return (int)Math.Min(120000,  (minRetryTime - DateTime.UtcNow).TotalMilliseconds);
						}

						return 1000;
					}

