set-variable.value:
@{
			var responseObj = context.Variables.GetValueOrDefault<JObject>("responseObject", new JObject());
			var arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
			var statusCode = context.Response?.StatusCode ?? 500;
			var callCompleted = context.Variables.GetValueOrDefault<bool>("callCompleted", false);
			var backendIndex = context.Variables.GetValueOrDefault<int>("backendIndex", -1);

			bool isTempError = statusCode == 429 || statusCode == 408 || statusCode == 400 || statusCode >= 500;
			bool isPermError = false;//!isTempError && (statusCode > 400 && statusCode < 500);
			var lastErrorReason = context.LastError?.Reason ?? "";
			var lastErrorMessage = context.LastError?.Message ?? "";
			if (lastErrorMessage.Length > 200) {
				lastErrorMessage = lastErrorMessage.Substring(0, 200) + "...";
			}

			arr.Add(new JObject {
				{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
				{ "message", "ON ERROR ENTERED: callCompleted: " + callCompleted +
					" backendIndex: " + backendIndex +
					" unThrottledBackends: " + context.Variables.GetValueOrDefault<int>("unThrottledBackends", -1) +
					" RetryRemaining: " + context.Variables.GetValueOrDefault<bool>("RetryRemaining", true) +
					" Return429: " + context.Variables.GetValueOrDefault<bool>("Return429", false) +
					" LastError: " + lastErrorReason + " - " + lastErrorMessage }
			});

			if (callCompleted) {
				if (isPermError) {
					responseObj["statusCode"] = statusCode;
					responseObj["statusReason"] = "Permanent Error";
				} else if (isTempError) {
					responseObj["statusCode"] = statusCode;
					responseObj["statusReason"] = "Temporary Error";
				} else {
					responseObj["statusCode"] = 500;
					responseObj["statusReason"] = "Unknown Error";
				}
			} else {
				JArray backends = context.Variables.GetValueOrDefault<JArray>("listBackends", new JArray());
				JArray priorityBackendIndxs = context.Variables.GetValueOrDefault<JArray>("PriBackendIndxs", new JArray());
				bool contextWindowExceeded = context.Variables.GetValueOrDefault<bool>("contextWindowExceeded", false);

				// A failure before backend selection leaves listBackends empty. Reporting No Backends
				// Available is factually impossible in that state -- a list that was never built cannot
				// be throttling -- and it buries the real fault (most often a rejected APIM subscription
				// key) behind a retryable capacity error. Surface the upstream status and the policy
				// error reason instead; the requeue and retry-after hints are suppressed below, because
				// retrying can never resolve a pre-routing failure.
				if (context.Variables.GetValueOrDefault<bool>("preRoutingFailure", false)) {
					responseObj["statusCode"] = statusCode >= 400 ? statusCode : 500;
					responseObj["statusReason"] = lastErrorReason.Length > 0
						? lastErrorReason
						: "Gateway Policy Error";
					return responseObj;
				}

				int unthrottledBackends = 0;

				foreach (int i in priorityBackendIndxs) {
					if (i < 0 || i >= backends.Count) { continue; }
					JObject backend = (JObject)backends[i];
					if (contextWindowExceeded && backend.Value<string>("label") == "PTU") { continue; }
					if (!backend.Value<bool>("isThrottling")) { unthrottledBackends++; }
				}

				// Retries are exhausted (on-error runs after the final attempt). If every eligible
				// backend is now throttling, there is no backend available: return a 429 so the client
				// can back off / requeue. The S7PREQUEUE header (below) only requests a requeue when configured.
				if (unthrottledBackends == 0) {
					responseObj["statusCode"] = 429;
					responseObj["statusReason"] = "No Backends Available";
					return responseObj;
				}

				if ( backendIndex < 0 || backendIndex >= backends.Count) {
					responseObj["statusCode"] = 500;
					responseObj["statusReason"] = "Invalid Backend Index";
					return responseObj;
				}

				// recalculate timeout or concurrency limit because retry did not happen
				var wasLimited = context.Variables.GetValueOrDefault<bool>("wasLimited", false);
				var startTime = context.Variables.GetValueOrDefault<DateTime>("CallAttemptStartTime", DateTime.UtcNow);
				var deltaSeconds = (DateTime.UtcNow - startTime).TotalSeconds;
				var requestTimeout = ((JObject)backends[backendIndex]).Value<int>("timeout");
				bool likelyTimeout = deltaSeconds >= (requestTimeout * 0.9);

				if ( likelyTimeout) {
					responseObj["statusCode"] = 408;
					responseObj["statusReason"] = "Timeout";
					statusCode = 408;
				} else if ( wasLimited ) {
					responseObj["statusCode"] = 429;
					responseObj["statusReason"] = "Concurrency Limit";
					statusCode = 429;
				} else {
					responseObj["statusCode"] = 500;
					responseObj["statusReason"] = "Unknown Error";
				}
			}

			// Error Handler
			arr.Add(new JObject {
				{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3") },
				{ "message", "ON ERROR HANDLER INVOKED-  callCompleted: " + callCompleted +
					" isPermError: " + isPermError +
					" isTempError: " + isTempError +
					" StatusCode: " + statusCode }
			});
			return responseObj;
		}

set-header.value:
@{
				JArray actLog = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
				string result = string.Join(" | ", actLog.Select(entry =>
					((JObject)entry).Value<string>("Elapsed") + "s " + ((JObject)entry).Value<string>("message")
				));
				return result.Length > 4000 ? result.Substring(0, 4000) + "..." : result;
			}

@{
				JArray errArr = context.Variables.GetValueOrDefault<JArray>("lastPolicyError", new JArray());
				if (errArr.Count > 0) { return errArr.ToString(Newtonsoft.Json.Formatting.None); }
				// lastPolicyError is only appended to by the inbound fragments. When the request never
				// reached them there is still a real APIM error to report, and returning an empty header
				// is exactly what makes a pre-routing failure look like an unexplained capacity problem.
				var reason = context.LastError?.Reason ?? "";
				var message = context.LastError?.Message ?? "";
				if (reason.Length == 0 && message.Length == 0) { return ""; }
				if (message.Length > 200) { message = message.Substring(0, 200) + "..."; }
				return new JObject { { "reason", reason }, { "message", message } }.ToString(Newtonsoft.Json.Formatting.None);
			}
